//! Embeds the app icon and version info into the Windows executable (`assets/icon.ico`,
//! regenerated by `cargo test -p soyuz-app --lib app_icon -- --ignored`).
//!
//! Needs the Windows SDK resource compiler (`rc.exe`, present with the MSVC build tools).
//! When it is missing the build continues without the embedded icon (the window icon is
//! drawn at runtime anyway).

fn main() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    println!("cargo:rerun-if-changed=build.rs");
    let target_windows = std::env::var("CARGO_CFG_TARGET_OS").is_ok_and(|os| os == "windows");
    if !(cfg!(windows) && target_windows) {
        return;
    }
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico")
        .set("ProductName", "Soyuz")
        .set("FileDescription", "Soyuz file explorer")
        .set("LegalCopyright", "Copyright (c) 2026 Aydemir Şahin and the Soyuz contributors. MIT License.");
    if let Err(e) = res.compile() {
        println!("cargo:warning=soyuz: icon not embedded ({e}); install the Windows SDK for rc.exe");
    }
}
